// TooltipContext.js
import { createContext, useState } from 'react';

const TooltipContext = createContext();

const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const openTooltip = (tooltip) => {
    setTooltip(tooltip);
  };

  const closeTooltip = () => {
    setTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, tooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export { TooltipProvider, TooltipContext };
```

```jsx
// Tooltip.js
import { useContext } from 'react';
import { TooltipContext } from './TooltipContext';

const Tooltip = ({ children, tooltip }) => {
  const { closeTooltip } = useContext(TooltipContext);

  if (!tooltip) return null;

  return (
    <div className="tooltip">
      <div className="tooltip-content">
        {tooltip}
        <button onClick={closeTooltip}>Close</button>
      </div>
    </div>
  );
};

export default Tooltip;
```

```jsx
// App.js
import { TooltipProvider } from './TooltipContext';
import Tooltip from './Tooltip';

const App = () => {
  return (
    <TooltipProvider>
      <div>
        <button onClick={() => openTooltip('Hello World!')}>Open Tooltip</button>
        <Tooltip tooltip="Hello World!" />
      </div>
    </TooltipProvider>
  );
};

export default App;
```

In this example, we create a `TooltipContext` using `createContext` from `react`. We then create a `TooltipProvider` component that wraps the app and provides the `openTooltip`, `closeTooltip`, and `tooltip` state to its children.

The `Tooltip` component uses the `useContext` hook to access the `closeTooltip` function and the `tooltip` state from the context. If the `tooltip` state is not null, it renders the tooltip with a close button.

When the close button is clicked, the `closeTooltip` function is called, which sets the `tooltip` state to null, closing the tooltip.

This way, we can open and close tooltips across different components without having to pass props down manually. We can also use the `TooltipProvider` to wrap the entire app, making the tooltip functionality available to all components. 

